import{_ as i,a0 as l,w as o,s as r,ao as d,I as p,x as s,a1 as a,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const F=JSON.parse('{"title":"使用 Flutter 开发简单的 Web 应用 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Flutter 开发简单的 Web 应用 | LCTT (201911) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Flutter 开发简单的 Web 应用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Flutter 开发简单的 Web 应用 | LCTT (201911) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201911/20191115 Developing a Simple Web Application Using Flutter","title":"使用 Flutter 开发简单的 Web 应用","tag":"201911","desc":""},"relativePath":"201911/20191115 Developing a Simple Web Application Using Flutter.md","filePath":"[post].md"}'),u={name:"201911/20191115 Developing a Simple Web Application Using Flutter.md"};function c(g,e,h,b,f,m){const t=l("Link");return o(),r("div",null,[e[15]||(e[15]=d(`<h1 id="使用-flutter-开发简单的-web-应用" tabindex="-1">使用 Flutter 开发简单的 Web 应用 <a class="header-anchor" href="#使用-flutter-开发简单的-web-应用" aria-label="Permalink to “使用 Flutter 开发简单的 Web 应用”">​</a></h1><p><img src="https://i1.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Screenshot-from-2019-11-15-16-20-30.png" alt=""></p><blockquote><p>本文指导读者如何使用 Flutter 运行和部署第一个 Web 应用。</p></blockquote><p>Flutter 在 Android 和 iOS 开发方面走了很长一段路之后，已经迈入了一个新的阶段，即 Web 开发。Google 发布了 Flutter 1.5，同时支持 Web 应用开发。</p><h3 id="为-web-开发配置-flutter" tabindex="-1">为 Web 开发配置 Flutter <a class="header-anchor" href="#为-web-开发配置-flutter" aria-label="Permalink to “为 Web 开发配置 Flutter”">​</a></h3><p>为了使用 Web 包，输入命令 <code>flutter upgrade</code> 更新到 Flutter 1.5.4。</p><ul><li>打开终端</li><li>输入 <code>flutter upgrade</code></li><li>输入 <code>flutter –version</code> 检查版本</li></ul><p><img src="https://i0.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Figure-1-Upgrading-Flutter-to-the-latest-version.jpg" alt="图 1: 升级 Flutter 到最新版"></p><p>也可以将 Android Studio 3.0 或更高版本用于 Flutter Web 开发，但在本教程中，我们使用 Visual Studio Code。</p><h3 id="使用-flutter-web-创建新项目" tabindex="-1">使用 Flutter Web 创建新项目 <a class="header-anchor" href="#使用-flutter-web-创建新项目" aria-label="Permalink to “使用 Flutter Web 创建新项目”">​</a></h3><p>打开 Visual Studio Code，然后按 <code>Shift+Ctrl+P</code> 开始一个新项目。输入 <code>flutter</code> 并选择 “New Web Project”。</p><p><img src="https://i0.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Figure-2-Starting-a-new-Flutter-Web-project-in-VSC.jpg" alt="图 2：在 VSC 中开始一个新的 Flatter 项目"></p><p>现在，为项目命名。我将其命名为 <code>open_source_for_you</code>。</p><p><img src="https://i2.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Figure-3-Naming-the-project.jpg" alt="图 3: 给项目命名"></p><p>在 VSC 中打开终端窗口，然后输入以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flutter packages pub global activate webdev</span></span>
<span class="line"><span>flutter packages upgrade</span></span></code></pre></div><p>现在，使用以下命令在 localhost 上运行网站，IP 地址是 127.0.0.1。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flutter packages pub global run webdev serve</span></span></code></pre></div><p>打开任何浏览器，然后输入 <code>http://127.0.0.1:8080/</code>。</p><p><img src="https://i0.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Figure-4-The-Flutter-demo-application-running-on-port-8080.jpg" alt="图 4：运行于 8080 端口的 Flutter 演示应用"></p><p>在项目目录中有个 Web 文件夹，其中包含了 <code>index.html</code>。<code>dart</code> 文件被编译成 JavaScript 文件，并使用以下代码包含在 HTML 文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;script defer src=&quot;main.dart.js&quot; type=&quot;application/javascript&quot;&gt;&lt;/script&gt;</span></span></code></pre></div><h3 id="编码和修改演示页面" tabindex="-1">编码和修改演示页面 <a class="header-anchor" href="#编码和修改演示页面" aria-label="Permalink to “编码和修改演示页面”">​</a></h3><p>让我们创建一个简单的应用，它会在网页上打印 “Welcome to OSFY”。</p><p>现在打开 Dart 文件，它位于 <code>lib</code> 文件夹 <code>main.dart</code>（默认名）中（参见图 5）。</p><p><img src="https://i2.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Figure-5-Location-of-main.dart-file.jpg" alt="图 5：main.dart 文件的位置"></p><p>现在，我们可以在 <code>MaterialApp</code> 的属性中删除调试标记，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>debugShowCheckedModeBanner: false</span></span></code></pre></div><p>现在，向 Dart 中添加更多内容与用 Dart 编写 Flutter 很类似。为此，我们可以声明一个名为 <code>MyClass</code> 的类，它继承了 <code>StatelessWidget</code>。</p><p>我们使用 <code>Center</code> 部件将元素定位到中心。我们还可以添加 <code>Padding</code> 部件来添加填充。使用以下代码获得图 5 所示的输出。使用刷新按钮查看更改。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>class MyClass extends StatelessWidget {</span></span>
<span class="line"><span>  @override</span></span>
<span class="line"><span>  Widget build(BuildContext context) {</span></span>
<span class="line"><span>    return Scaffold(</span></span>
<span class="line"><span>      body: Center(</span></span>
<span class="line"><span>        child: Column(</span></span>
<span class="line"><span>          mainAxisAlignment: MainAxisAlignment.center,</span></span>
<span class="line"><span>          children: &lt;Widget&gt;[</span></span>
<span class="line"><span>            Padding(</span></span>
<span class="line"><span>              padding: EdgeInsets.all(20.0),</span></span>
<span class="line"><span>              child: Text(</span></span>
<span class="line"><span>                &#39;Welcome to OSFY&#39;,</span></span>
<span class="line"><span>                style: TextStyle(fontSize: 24.0, fontWeight: FontWeight.bold),</span></span>
<span class="line"><span>              ),</span></span>
<span class="line"><span>            ),</span></span>
<span class="line"><span>          ],</span></span>
<span class="line"><span>        ),</span></span>
<span class="line"><span>      ),</span></span>
<span class="line"><span>    );</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><img src="https://i2.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Figure-6-Output-of-MyClass.jpg" alt="图 6：MyClass 的输出"></p><p>让我们从互联网中添加一张图片，我已经从一个杂志网站选择了一张 “Open Source for You” 徽标。我们使用 <code>Image.network</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Image.network(</span></span>
<span class="line"><span>  &#39;https://opensourceforu.com/wp-content/uploads/2014/03/OSFY-Logo.jpg&#39;,</span></span>
<span class="line"><span>  height: 100,</span></span>
<span class="line"><span>  width: 150</span></span>
<span class="line"><span>),</span></span></code></pre></div><p>最终输出如图 7 所示。</p><p><img src="https://i0.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Figure-7-Final-output.jpg" alt="图 7：最终输出"></p><hr>`,37)),p("p",null,[e[1]||(e[1]=s("via: ",-1)),a(t,{href:"https://opensourceforu.com/2019/11/developing-a-simple-web-application-using/"},{default:n(()=>[...e[0]||(e[0]=[s("https://opensourceforu.com/2019/11/developing-a-simple-web-application-using/",-1)])]),_:1})]),p("p",null,[e[6]||(e[6]=s("作者：",-1)),a(t,{href:"https://opensourceforu.com/author/jis-joe/"},{default:n(()=>[...e[2]||(e[2]=[s("Jis Joe Mathew",-1)])]),_:1}),e[7]||(e[7]=s(" 选题：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:n(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[8]||(e[8]=s(" 译者：",-1)),a(t,{href:"https://github.com/geekpi"},{default:n(()=>[...e[4]||(e[4]=[s("geekpi",-1)])]),_:1}),e[9]||(e[9]=s(" 校对：",-1)),a(t,{href:"https://github.com/wxy"},{default:n(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),p("p",null,[e[12]||(e[12]=s("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原创编译，",-1)),a(t,{href:"https://linux.cn/"},{default:n(()=>[...e[11]||(e[11]=[s("Linux中国",-1)])]),_:1}),e[14]||(e[14]=s(" 荣誉推出",-1))])])}const w=i(u,[["render",c]]);export{F as __pageData,w as default};
